import { toDatabase } from '../cif/schema.js';
import { ReaderResult as Result } from '../result.js';
import { Column } from '../../../mol-data/db.js';
import { RelionStar_Aliases, RelionStar_Schema } from './schema.js';
const CoordinateFieldAliases = [
    'rlnCenteredCoordinateXAngst',
    'rlnCenteredCoordinateXAngstrom',
    'rlnCoordinateX',
    'wrpCoordinateX1',
];
function hasCoordinateFields(block) {
    return CoordinateFieldAliases.some(name => !!block.categories[name]);
}
function findParticlesBlock(file) {
    let fallback;
    for (const block of file.blocks) {
        if (!hasCoordinateFields(block))
            continue;
        if (!fallback)
            fallback = block;
        if (block.header.toLowerCase().includes('particle'))
            return block;
    }
    return fallback;
}
function findOpticsBlock(file) {
    for (const block of file.blocks) {
        if (block.header.toLowerCase().includes('optics'))
            return block;
    }
}
export function parseRelionStar(file) {
    const particleBlock = findParticlesBlock(file);
    if (!particleBlock) {
        return Result.error('No RELION particle data block with coordinates was found.');
    }
    const opticsBlock = findOpticsBlock(file);
    const particles = toDatabase(RelionStar_Schema, particleBlock, RelionStar_Aliases).particles;
    const optics = opticsBlock
        ? toDatabase(RelionStar_Schema, opticsBlock, RelionStar_Aliases).optics
        : undefined;
    return Result.success({
        source: file,
        particleBlock,
        opticsBlock,
        particles,
        optics,
    });
}
export function getRelionStarTomogramNames(file) {
    const result = parseRelionStar(file);
    if (result.isError)
        return [];
    const tomoName = result.result.particles.rlnTomoName;
    if (!tomoName.isDefined)
        return [];
    const tomograms = new Set();
    for (let row = 0, n = tomoName.rowCount; row < n; ++row) {
        if (tomoName.valueKind(row) !== Column.ValueKinds.Present)
            continue;
        const v = tomoName.value(row);
        if (v)
            tomograms.add(v);
    }
    return Array.from(tomograms).sort();
}
export function getRelionStarMicrographNames(file) {
    const result = parseRelionStar(file);
    if (result.isError)
        return [];
    const micrographName = result.result.particles.rlnMicrographName;
    if (!micrographName.isDefined)
        return [];
    const micrographs = new Set();
    for (let row = 0, n = micrographName.rowCount; row < n; ++row) {
        if (micrographName.valueKind(row) !== Column.ValueKinds.Present)
            continue;
        const v = micrographName.value(row);
        if (v)
            micrographs.add(v);
    }
    return Array.from(micrographs).sort();
}
